# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OĞLU HÜSEYİN\'DEN EMİNE ANA\'YA MEKTUPLAR VE MEKTUP PLANI</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Metnin Teması ve Hikâye Unsurları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• {koyu:Tema:} Vatan sevgisi, Millî Mücadele ve Atatürk.</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• {koyu:Kişiler:} Cephedeki asker Hüseyin, annesi</text>\n  <text x="50" y="138" font-size="11" fill="#334155">Emine Ana, Başkomutan Mustafa Kemal Paşa.</text>\n  <text x="40" y="160" font-size="11" fill="#334155">• {koyu:Zaman / Mekân:} Kurtuluş Savaşı / Cephe.</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• {koyu:Ana Fikir:} Türk milleti ve ordusu, Atatürk\'ün</text>\n  <text x="50" y="200" font-size="11" font-weight="bold" fill="#1e40af">önderliğinde fedakârlıkla vatanı kurtarmıştır.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Mektup Türünün Biçimsel Bölümleri</text>\n  <text x="650" y="96" text-anchor="end" font-size="11" font-weight="bold" fill="#854d0e">1. Sağ Üst Köşe: Yer ve Tarih (Ankara, 10.11.2026)</text>\n  <text x="380" y="118" font-size="11" font-weight="bold" fill="#713f12">2. Hitap Başlığı: "Canım Annem," (Büyük harf + virgül)</text>\n  <text x="380" y="142" font-size="11" fill="#334155">3. Giriş Bölümü: Hal hatır sorma ve mektubun amacı.</text>\n  <text x="380" y="164" font-size="11" fill="#334155">4. Gelişme Bölümü: Asıl anlatılmak istenen duygu/olaylar.</text>\n  <text x="380" y="186" font-size="11" fill="#334155">5. Sonuç Bölümü: Sevgi, saygı ve iyi dilek ifadeleri.</text>\n  <text x="380" y="208" font-size="11" font-weight="bold" fill="#854d0e">6. Sağ Alt: Ad-Soyad ve İmza  |  Sol Alt: Adres</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİL YAPILARI: KELİMEDE KÖK VE EK (YAPIM - ÇEKİM EKLERİ)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kök Kavramı (İsim Kökü - Fiil Kökü)</text>\n  <text x="182" y="96" text-anchor="middle" font-size="11" fill="#334155">Kelimenin anlamlı en küçük parçasına KÖK denir.</text>\n  <text x="45" y="122" font-size="12" font-weight="bold" fill="#14532d">• İsim (Ad) Kökü (-mak/-mek almaz):</text>\n  <text x="55" y="142" font-size="11" fill="#334155">vatan, göz, su, kalem, yol, bayrak</text>\n  <text x="45" y="170" font-size="12" font-weight="bold" fill="#14532d">• Fiil (Eylem) Kökü (-mak/-mek alır):</text>\n  <text x="55" y="190" font-size="11" fill="#334155">yaz- (yazmak), sev- (sevmek), oku- (okumak)</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Kök ile kelimenin tamamı arasında anlam bağı vardır!</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Yapım Ekleri ve Çekim Ekleri</text>\n  <text x="380" y="100" font-size="12" font-weight="bold" fill="#6b21a8">• Yapım Eki (Yeni anlamlı kelime türetir):</text>\n  <text x="390" y="120" font-size="11" fill="#334155">-li, -siz, -ci, -lik, -gi (göz ➔ gözlük ➔ gözlükçü)</text>\n  <text x="390" y="140" font-size="11" fill="#334155">(sev- ➔ sevgi ➔ sevgili), (vatan ➔ vatandaş)</text>\n  <text x="380" y="170" font-size="12" font-weight="bold" fill="#6b21a8">• Çekim Eki (Kelimenin anlamını değiştirmez):</text>\n  <text x="390" y="190" font-size="11" fill="#334155">-ler/-lar, -de, -den, -i, -im (mektup ➔ mektuplarım)</text>\n  <text x="390" y="210" font-size="11" fill="#334155">(asker ➔ askerlerimizden)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAĞLANTI İFADELERİ, YAZIM VE NOKTALAMA KURALLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Bağlantı ve Geçiş İfadeleri</text>\n  <text x="45" y="100" font-size="12" font-weight="bold" fill="#9f1239">• Düşüncenin Yönünü Değiştirenler:</text>\n  <text x="55" y="120" font-size="11" fill="#334155">ama, fakat, lakin, ancak, oysa, buna rağmen</text>\n  <text x="45" y="148" font-size="12" font-weight="bold" fill="#9f1239">• Destekleyici ve Açıklayıcı Olanlar:</text>\n  <text x="55" y="168" font-size="11" fill="#334155">hatta, üstelik, ayrıca, yani, başka bir deyişle</text>\n  <text x="45" y="196" font-size="12" font-weight="bold" fill="#9f1239">• Özetleyen ve Sonuç Bildirenler:</text>\n  <text x="55" y="216" font-size="11" fill="#334155">kısacası, özetle, sonuç olarak, böylece</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Yazım ve Noktalama İpuçları</text>\n  <text x="380" y="100" font-size="11" fill="#334155">• Mektup hitaplarında her kelime büyük harfle</text>\n  <text x="390" y="118" font-size="11" font-weight="bold" fill="#155e75">başlar ve sonuna virgül konur: Sevgili Kardeşim,</text>\n  <text x="380" y="144" font-size="11" fill="#334155">• Belirli bir tarih bildiren ay ve gün adları büyük</text>\n  <text x="390" y="162" font-size="11" font-weight="bold" fill="#155e75">harfle yazılır: 10 Kasım 1938\'de, 29 Ekim\'de.</text>\n  <text x="380" y="188" font-size="11" fill="#334155">• Özel adlara gelen çekim ekleri kesme işaretiyle (\')</text>\n  <text x="390" y="206" font-size="11" font-weight="bold" fill="#155e75">ayrılır; yapım ekleri ayrılmaz (Türkçenin, Ankaralı).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
